CHAPTERS=[('II/08', 'Differentiability in Several Variables', 'ch08_differentiability_in_several_variables'), ('II/09', 'Inverse and Implicit Function Principles', 'ch09_inverse_and_implicit_function_principles'), ('II/10', 'Riemann Integration', 'ch10_riemann_integration'), ('II/11', 'Pointwise and Uniform Convergence', 'ch11_pointwise_and_uniform_convergence'), ('II/12', 'Interchanging Limits, Derivatives and Integrals', 'ch12_interchanging_limits_derivatives_and_integrals'), ('II/13', 'Infinite Series of Functions', 'ch13_infinite_series_of_functions'), ('II/14', 'Trigonometric Series', 'ch14_trigonometric_series'), ('II/15', 'Pathological and Nowhere-Differentiable Functions', 'ch15_pathological_and_nowhere_differentiable_functions'), ('II/16', 'Contraction Mappings', 'ch16_contraction_mappings'), ('II/17', 'Brouwer-Type Fixed-Point Ideas', 'ch17_brouwer_type_fixed_point_ideas'), ('II/18', 'Integral Equations', 'ch18_integral_equations'), ('II/19', 'Elementary Existence Theory for ODEs', 'ch19_elementary_existence_theory_for_odes'), ('II/20', 'Polynomial Interpolation', 'ch20_polynomial_interpolation'), ('II/21', 'Polynomial Approximation', 'ch21_polynomial_approximation'), ('II/22', 'Chebyshev and Minimax Approximation', 'ch22_chebyshev_and_minimax_approximation'), ('II/23', 'The Alternation Principle', 'ch23_the_alternation_principle'), ('II/24', 'Numerical Quadrature', 'ch24_numerical_quadrature'), ('II/25', 'Continued Fractions and Approximation Topics', 'ch25_continued_fractions_and_approximation_topics')]
DATA={'II/13': {'intro': 'Infinite series of functions are controlled most effectively by uniform comparison tests. Absolute and uniform convergence turn termwise algebra, integration, and sometimes differentiation into rigorous operations.', 'sections': [('Partial sums', 'A function series is studied through its partial-sum sequence.'), ('Uniform convergence', 'Uniform convergence of partial sums is the key global notion.'), ('Weierstrass M-test', 'Uniform domination by a summable numerical series gives uniform absolute convergence.'), ('Power series', 'Inside the radius of convergence, power series converge uniformly on compact subintervals.'), ('Algebra of series', 'Uniformly convergent series can be added and scaled termwise.'), ('Integration', 'Uniform convergence justifies termwise integration.'), ('Differentiation', 'Uniform convergence of derivative series plus one-point convergence justifies termwise differentiation.'), ('Remainder bounds', 'Majorant tails provide explicit uniform truncation error estimates.')], 'theorems': [('Weierstrass M-test', 'If $|f_n(x)|\\le M_n$ for all $x$ and $\\sum M_n<\\infty$, then $\\sum f_n$ converges uniformly and absolutely.', 'The numerical tail bound $\\sum_{n>N}M_n$ controls every function tail uniformly, so the partial sums are uniformly Cauchy.'), ('Uniform termwise integration', 'A uniformly convergent series of integrable functions may be integrated termwise.', 'Apply the uniform-limit integral theorem to partial sums.'), ('Power-series local uniformity', 'A power series converges uniformly on every closed subinterval strictly inside its radius of convergence.', 'Choose a larger interior radius and dominate coefficients times $r^n$ by a convergent geometric comparison from the root or ratio test.')], 'dossiers': [('M-test with geometric majorant', 'Show $\\sum x^n/n^2$ converges uniformly on $[-1,1]$.', '$|x^n/n^2|\\le1/n^2$ and $\\sum1/n^2$ converges.'), ('Uniform tail bound', 'If $|f_n|\\le2^{-n}$, bound the tail after $N$.', 'The sup tail is at most $\\sum_{n>N}2^{-n}=2^{-N}$.'), ('Harmonic obstruction', 'Why does the M-test fail for $x^n/n$ on $[0,1]$?', 'The natural majorant $1/n$ diverges; indeed at $x=1$ the series is harmonic.'), ('Power-series compact convergence', 'Why does $\\sum x^n$ converge uniformly on $[-r,r]$ for $r<1$?', '$|x^n|\\le r^n$ and the geometric series converges.'), ('Termwise integral', 'Integrate $\\sum_{n\\ge0}x^n$ on $[0,r]$, $r<1$.', 'Uniform convergence gives $\\sum r^{n+1}/(n+1)=-\\log(1-r)$.'), ('A derivative series', 'For $\\sum x^n/n!$, justify termwise differentiation on bounded intervals.', 'Derivative terms are $x^{n-1}/(n-1)!$, uniformly dominated on $[-R,R]$ by $R^{n-1}/(n-1)!$.'), ('Absolute versus uniform', 'Does pointwise absolute convergence imply uniform convergence?', 'No. Uniformity requires tail control independent of $x$; absolute convergence can deteriorate as $x$ varies.'), ('Uniform Cauchy criterion', 'State it for a series.', 'For every epsilon there is $N$ such that every finite tail $\\sum_{n=p}^qf_n(x)$ has magnitude below epsilon for all $x$ whenever $q\\ge p\\ge N$.'), ('Remainder estimate', 'If $|f_n|\\le M_n$, how can one certify truncation accuracy?', 'Bound the sup error by the numerical tail $\\sum_{n>N}M_n$.'), ('Uniform convergence preserves continuity', 'Why is a uniformly convergent series of continuous functions continuous?', 'Its partial sums are continuous and converge uniformly, so the uniform-limit theorem applies.'), ('Local uniformity on noncompact domains', 'What does it mean for a series to converge locally uniformly?', 'It converges uniformly on every compact subset of the domain.'), ('Series synthesis', 'Why are majorants central?', 'They replace a difficult family of function tails by one numerical tail independent of the point, converting pointwise estimates into uniform convergence.')], 'exercises': [('Apply M-test to $\\sum x^n/2^n$ on $[-1,1]$.', 'Use $(1/2)^n$.', 'It converges uniformly.'), ('Does $\\sum x^n$ converge uniformly on $[0,1]$?', 'Check $x=1$.', 'No; it does not even converge there.'), ('Uniform convergence of $\\sum f_n$ means what for partial sums?', 'Use the definition.', 'Partial sums converge uniformly.'), ('If $\\sum M_n$ converges, what about its tails?', 'Cauchy criterion.', 'They tend to zero.'), ('Can a uniformly convergent series of continuous functions be discontinuous?', 'No.', 'Its sum is continuous.'), ('What is a power-series radius?', 'Boundary between convergence and divergence.', 'A number $R$ such that convergence holds for $|x-a|<R$ and divergence for $|x-a|>R$.'), ('Can the M-test prove absolute convergence?', 'Yes.', 'It gives uniform absolute convergence.'), ('How do you estimate a remainder under M-test?', 'Use majorant tail.', 'By $\\sum_{n>N}M_n$.')]}, 'II/14': {'intro': 'Trigonometric series represent periodic functions in orthogonal sine and cosine modes. The first layer of Fourier analysis concerns coefficients, orthogonality, partial sums, and the distinction between formal expansions and genuine convergence.', 'sections': [('Periodic functions', 'Periodicity identifies functions on the line with functions on a circle.'), ('Trigonometric system', 'Sines and cosines form an orthogonal family on a full period.'), ('Fourier coefficients', 'Coefficients are obtained by inner products with the trigonometric modes.'), ('Partial sums', 'Finite Fourier sums are trigonometric polynomials.'), ('Bessel inequality', 'Orthogonality bounds the square-sum of coefficients by the $L^2$ energy.'), ('Dirichlet kernel', 'Partial sums can be written as convolution with the Dirichlet kernel.'), ('Pointwise convergence ideas', 'Smoothness and one-sided limits influence pointwise convergence.'), ('Parseval preview', 'When the system is complete, coefficient energy equals function energy.')], 'theorems': [('Orthogonality relations', 'Distinct sine/cosine modes are orthogonal on $[-\\pi,\\pi]$.', 'Use product-to-sum identities; integrals of nonconstant integer-frequency sines and cosines over a full period vanish.'), ('Bessel inequality', 'For an orthonormal family, the sum of squared Fourier coefficients is bounded by the squared norm of the function.', 'Subtract the finite orthogonal projection and expand its nonnegative squared norm.'), ('Dirichlet midpoint principle', 'Under standard piecewise smooth hypotheses, Fourier sums converge at a jump to the midpoint of one-sided limits.', 'Rewrite the partial sum using the Dirichlet kernel and use oscillatory cancellation away from the origin plus local one-sided regularity.')], 'dossiers': [('Coefficient of a constant', 'Find the Fourier coefficients of $f(x)=1$.', 'Only the constant coefficient is nonzero; all sine and positive cosine modes integrate to zero.'), ('Odd symmetry', 'What coefficients vanish for an odd function?', 'The constant and cosine coefficients vanish; only sine coefficients may remain.'), ('Even symmetry', 'What coefficients vanish for an even function?', 'All sine coefficients vanish.'), ('Orthogonality computation', 'Compute $\\int_{-\\pi}^{\\pi}\\cos(nx)\\cos(mx)dx$ for $n\\ne m$.', 'Product-to-sum reduces it to integrals of nonconstant cosine modes, hence zero.'), ('Sawtooth structure', 'Why does an odd sawtooth have a sine-only series?', 'Odd symmetry kills the even cosine modes and constant term.'), ('Finite projection', 'Why is the $N$th Fourier partial sum the best $L^2$ approximation among trigonometric polynomials of degree at most $N$?', 'It is the orthogonal projection onto that finite-dimensional subspace.'), ('Bessel estimate', 'If $\\|f\\|_2=1$, what can be said about Fourier coefficients?', 'Their squared magnitudes have total finite partial sums bounded by $1$.'), ('Dirichlet kernel integral', 'Why must the Dirichlet kernel have total mass $2\\pi$ under the standard normalization?', 'The partial-sum operator reproduces constants, so integrating the kernel against the constant function must return that constant.'), ('Jump value', 'What Fourier value is expected at a jump from $L_-$ to $L_+$?', 'The midpoint $(L_-+L_+)/2$ under Dirichlet hypotheses.'), ('Gibbs warning', 'What does Gibbs phenomenon say qualitatively?', 'Near jumps, partial sums exhibit persistent overshoot whose width shrinks but relative amplitude does not vanish.'), ('Parseval meaning', "Interpret Parseval's identity.", 'It says the orthogonal mode coefficients preserve total quadratic energy.'), ('Trigonometric synthesis', 'Why are Fourier coefficients canonical?', 'Orthogonality isolates each mode by an inner product, making coefficients invariantly determined by projection rather than by solving a coupled system.')], 'exercises': [('What modes survive for an even function?', 'Parity.', 'Constant and cosines.'), ('What modes survive for an odd function?', 'Parity.', 'Sines.'), ('Are $\\sin nx$ and $\\cos mx$ orthogonal?', 'Parity/product identities.', 'Yes on a full symmetric period.'), ('What is a trigonometric polynomial?', 'Finite linear combination.', 'A finite combination of constant, sine, and cosine modes.'), ('What is Bessel inequality about?', 'Coefficient energy.', 'It bounds coefficient square-sums by function energy.'), ('At a smooth point, what value is expected from Fourier convergence?', 'The function value.', 'The ordinary value.'), ('At a jump, what value is expected?', 'Average of one-sided limits.', 'Their midpoint.'), ('What operator is the Fourier partial sum?', 'Orthogonal projection in $L^2$.', 'Projection onto the first modes.')]}, 'II/15': {'intro': 'Pathological functions reveal the sharp limits of naive intuition. Continuity need not imply differentiability, pointwise limits can destroy regularity, and dense oscillation can coexist with precise global structure.', 'sections': [('Everywhere continuous, nowhere differentiable', 'Weierstrass-type series show continuity can coexist with complete failure of classical tangents.'), ('Oscillation across scales', 'High-frequency components with slowly decaying amplitude create roughness at every scale.'), ('Cantor-type functions', 'Monotone continuous functions can have derivative zero on a large set yet still increase globally.'), ('Pointwise-limit pathologies', 'Limits can lose continuity when convergence is not uniform.'), ('Dense discontinuities', 'Functions may be discontinuous on dense sets while retaining integrability properties.'), ('Baire viewpoint', 'Category methods explain why rough functions are abundant rather than exceptional.'), ('Moduli of continuity', 'Hölder estimates quantify regularity below differentiability.'), ('Lessons for hypotheses', 'Counterexamples identify which assumptions in major theorems are genuinely necessary.')], 'theorems': [('Uniform convergence of a Weierstrass series', 'If $\\sum a^n\\cos(b^nx)$ has $0<a<1$, then it converges uniformly and defines a continuous function.', 'Each term is bounded by $a^n$ and the geometric majorant converges; the uniform limit of continuous functions is continuous.'), ('Cantor-function monotonicity', 'The Cantor function is continuous, nondecreasing, and constant on every removed middle-third interval.', 'Its ternary/binary digit construction preserves order; uniform approximants are continuous monotone functions and stabilize on removed intervals.'), ('Hölder roughness principle', 'A Hölder estimate $|f(x)-f(y)|\\le C|x-y|^\\alpha$ with $0<\\alpha<1$ permits much rougher behavior than Lipschitz regularity.', 'The quotient by $|x-y|$ may grow like $|x-y|^{\\alpha-1}$, so differentiability is not forced.')], 'dossiers': [('Uniform continuity of Weierstrass partial sums', 'Why does the geometric amplitude guarantee a continuous limit?', 'The M-test gives uniform convergence, and uniform limits preserve continuity.'), ('Derivative heuristic', 'Why can differentiating $a^n\\cos(b^nx)$ termwise be dangerous when $ab>1$?', 'Derivative amplitudes behave like $(ab)^n$, which grow rather than decay, signaling loss of derivative control.'), ('Cantor function and derivative zero', 'How can a nonconstant monotone function have derivative zero on a dense open set?', 'It is constant on each complementary middle-third interval; the union of these intervals is dense and open, yet the function increases through the Cantor set.'), ('Pointwise discontinuous limit', 'Use $x^n$ on $[0,1]$ to exhibit a discontinuous pointwise limit.', 'The limit is $0$ on $[0,1)$ and $1$ at $1$.'), ('Dirichlet function', 'What is special about $1_{\\mathbb Q}$?', 'It is discontinuous at every real point because every interval contains both rationals and irrationals.'), ('Thomae contrast', "Describe why Thomae's function is discontinuous at rationals but continuous at irrationals.", 'Large values occur only at rationals with small denominators, of which there are finitely many in a bounded interval; near an irrational one can avoid those finitely many.'), ('Hölder but not Lipschitz', 'Show $f(x)=\\sqrt{|x|}$ is Hölder-$1/2$ but not Lipschitz near zero.', '$|\\sqrt{|x|}-\\sqrt{|y|}|\\le\\sqrt{|x-y|}$, while $|f(x)-f(0)|/|x|=1/\\sqrt{|x|}\\to\\infty$.'), ('Dense set of discontinuities', 'Can a Riemann-integrable function have a dense set of discontinuities?', "Yes; Thomae's function is Riemann integrable and discontinuous at every rational, a dense set of measure zero."), ('Nowhere differentiability lesson', 'Why does continuity alone not control local slope?', 'Continuity bounds function increments absolutely, but differentiability requires increments to be asymptotically linear relative to distance.'), ('Uniform-limit protection', 'Which pathology does uniform convergence prevent?', 'It prevents continuous approximants from converging to a discontinuous limit.'), ('Hypothesis testing', 'How should a counterexample be used when reading a theorem?', 'Remove one hypothesis at a time and see whether the conclusion fails; a sharp counterexample shows that hypothesis controls a real mechanism.'), ('Pathology synthesis', 'Why are pathological examples central to analysis?', 'They separate intuition based on smooth finite-dimensional examples from the exact logical content of definitions and theorems.')], 'exercises': [('Is every continuous function differentiable somewhere?', 'Think of nowhere-differentiable examples.', 'No.'), ('Does uniform limit of continuous functions stay continuous?', 'Yes.', 'Yes.'), ('Does pointwise limit?', 'Use $x^n$.', 'Not necessarily.'), ('Can a monotone function be constant on dense open pieces yet nonconstant globally?', 'Cantor function.', 'Yes.'), ('Is $\\sqrt{|x|}$ Lipschitz near zero?', 'Check quotient.', 'No.'), ('Is it Hölder-$1/2$?', 'Use square-root inequality.', 'Yes.'), ("Is Dirichlet's function Riemann integrable?", 'Upper/lower sums.', 'No.'), ('Why study counterexamples?', 'Test hypotheses.', 'They reveal necessity and boundaries of theorems.')]}, 'II/16': {'intro': 'The contraction mapping theorem turns a quantitative shrinking estimate into existence, uniqueness, and an algorithm. It is one of the cleanest bridges between analysis and computation.', 'sections': [('Contractions', 'A contraction reduces all distances by a fixed factor $q<1$.'), ('Fixed points', 'A fixed point solves $Tx=x$.'), ('Picard iteration', 'Repeated application $x_{n+1}=Tx_n$ is the natural algorithm.'), ('Completeness', 'The iteration is Cauchy because geometric distance estimates telescope; completeness supplies the limit.'), ('Uniqueness', 'Two fixed points would be strictly closer after applying $T$, impossible unless equal.'), ('Error estimates', 'A priori and a posteriori geometric bounds quantify iteration error.'), ('Parameter dependence', 'Contractive fixed points vary stably under perturbations.'), ('Applications', 'Integral equations and ODEs can be reformulated as fixed-point problems.')], 'theorems': [('Banach fixed-point theorem', 'A contraction on a nonempty complete metric space has a unique fixed point, and every Picard iteration converges to it.', 'The successive differences decay geometrically, making iterates Cauchy. Completeness gives a limit; continuity of the contraction makes it fixed; the contraction inequality gives uniqueness.'), ('A priori error bound', 'If $x_{n+1}=Tx_n$ and contraction factor is $q$, then $d(x_n,x_*)\\le q^n(1-q)^{-1}d(x_1,x_0)$.', 'Bound the tail by the geometric sum of successive differences.'), ('Stability under perturbation', 'If contractions $T,S$ share factor $q<1$ and fixed points $x_T,x_S$, then $d(x_T,x_S)\\le(1-q)^{-1}\\sup_x d(Tx,Sx)$.', 'Insert and subtract $Tx_S$ and use the contraction bound before rearranging.')], 'dossiers': [('Affine contraction', 'Solve $x=(x+3)/4$.', 'The map has factor $1/4$ and fixed point $x=1$.'), ('Iteration rate', 'How many powers of $q$ control the error?', 'Error decays geometrically like $q^n$, up to the prefactor determined by the first step.'), ('Uniqueness proof', 'Show two fixed points must coincide.', '$d(x,y)=d(Tx,Ty)\\le qd(x,y)$; since $q<1$, the distance is zero.'), ('Why completeness matters', 'Give a contraction on an incomplete space with no fixed point.', 'On $(0,1)$, $T(x)=(x+1)/2$ is a contraction whose fixed point $1$ lies outside the space.'), ('Matrix contraction', 'When is $T(x)=Ax+b$ a Euclidean contraction?', 'Whenever the operator norm $\\|A\\|_2<1$.'), ('Fixed-point series', 'Solve $x=Ax+b$ with $\\|A\\|<1$.', '$x=(I-A)^{-1}b=\\sum_{n\\ge0}A^n b$, with convergence from the geometric operator-norm bound.'), ('A posteriori estimate', 'Bound $d(x_n,x_*)$ using $d(x_n,x_{n-1})$.', 'The tail is at most $d(x_n,x_{n-1})/(1-q)$.'), ('Nested mapping', 'Why must $T$ map the complete set into itself?', 'Otherwise the iteration may leave the domain and the completeness argument no longer applies.'), ('Parameter stability', 'What happens if $T$ is perturbed by at most epsilon uniformly?', 'The fixed point moves by at most $\\varepsilon/(1-q)$.'), ('Integral-equation preview', 'How does an integral operator become a contraction?', 'Bound the sup-norm difference of outputs by an interval-length times a Lipschitz constant times the input sup difference.'), ('ODE preview', "How does Picard iteration arise for $y'=f(t,y)$?", 'Rewrite as $y(t)=y_0+\\int f(s,y(s))ds$ and iterate the integral operator.'), ('Contraction synthesis', 'Why is this theorem algorithmic?', 'Its proof constructs the solution by iteration and simultaneously provides computable geometric error bounds.')], 'exercises': [('Find fixed point of $T(x)=x/2+1$.', 'Solve algebraically.', 'It is $2$.'), ('What is the contraction factor?', 'Coefficient of $x$.', '$1/2$.'), ('Why unique?', 'Use fixed-point inequality.', 'Two fixed points have zero distance.'), ('Does a contraction have to be linear?', 'No.', 'No.'), ('What property supplies the limit?', 'Completeness.', 'Completeness of the space.'), ('What sequence is used?', 'Picard iteration.', '$x_{n+1}=Tx_n$.'), ('What is the qualitative error rate?', 'Geometric.', 'Order $q^n$.'), ('Can $q=1$ be used?', 'No strict contraction.', "Not in Banach's theorem.")]}, 'II/17': {'intro': "Brouwer-type fixed-point ideas replace metric contraction by topology. Existence can survive without uniqueness or an iterative rate, revealing a distinct mechanism from Banach's theorem.", 'sections': [('Fixed points without contraction', 'Continuous maps can have fixed points for topological rather than metric reasons.'), ('Interval case', 'The intermediate-value theorem already yields a one-dimensional Brouwer theorem.'), ('Convex compact sets', "Brouwer's theorem applies to continuous self-maps of compact convex subsets of Euclidean space."), ('No-retraction intuition', 'A ball cannot continuously retract onto its boundary.'), ('Degree intuition', 'Topological degree counts preimages with orientation and obstructs disappearance of fixed points.'), ('Existence versus uniqueness', 'Brouwer gives existence but generally no uniqueness.'), ('Applications', 'Equilibria in games, economics, and nonlinear systems often use Brouwer-type existence.'), ('Comparison with Banach', 'Banach is quantitative and metric; Brouwer is qualitative and topological.')], 'theorems': [('Interval fixed-point theorem', 'Every continuous $f:[a,b]\\to[a,b]$ has a fixed point.', 'Apply the intermediate-value theorem to $g(x)=f(x)-x$: $g(a)\\ge0$ and $g(b)\\le0$.'), ('Brouwer fixed-point theorem', 'Every continuous map from a nonempty compact convex subset of $\\mathbb R^n$ to itself has a fixed point.', "The full proof uses a topological obstruction such as no-retraction, Sperner's lemma, or degree; the key point is that a fixed-point-free map would induce impossible boundary data."), ('No-retraction consequence', 'There is no continuous retraction from the closed ball onto its boundary sphere.', 'A retraction would contradict Brouwer by composing radial constructions to obtain a fixed-point-free self-map of the ball.')], 'dossiers': [('Interval proof', 'Prove the fixed-point theorem on $[0,1]$.', 'For $g=f-\\mathrm{id}$, $g(0)\\ge0$ and $g(1)\\le0$; continuity gives a zero.'), ('Failure without compactness', 'Give a continuous self-map of $(0,1)$ with no fixed point.', '$f(x)=(x+1)/2$ maps $(0,1)$ to itself and has only fixed point $1$, outside the domain.'), ('Failure without self-map condition', 'Why does $f(x)=x+1$ on $[0,1]$ not contradict Brouwer?', 'Its image is not contained in $[0,1]$.'), ('Nonuniqueness', 'Give a Brouwer map with many fixed points.', 'The identity map fixes every point.'), ('Banach versus Brouwer', 'Which theorem gives an iteration rate?', 'Banach does; Brouwer generally supplies existence only.'), ('Convexity role', "Why is an annulus not covered directly by Brouwer's convex-set statement?", 'An annulus is not convex; straight segments between points may leave it.'), ('A rotation of a disk', 'Why must a disk rotation have a fixed point?', 'The center is fixed, consistent with Brouwer.'), ('Sperner intuition', "How does Sperner's lemma relate to Brouwer?", 'A labeled triangulation forces a fully labeled simplex; shrinking mesh sizes produce approximate fixed points whose compactness limit is an exact one.'), ('Equilibrium interpretation', 'How can a fixed point encode equilibrium?', 'A response map sends a state to its updated best-response or normalized state; a fixed point is unchanged by the update and thus represents equilibrium.'), ('Topological obstruction', "What does 'no retraction' mean intuitively?", 'One cannot continuously push every interior point to the boundary while leaving boundary points fixed.'), ('Approximate fixed points', 'Why are compactness arguments natural in Brouwer proofs?', 'Combinatorial or discretized arguments produce approximate fixed points; compactness extracts a convergent subsequence and continuity turns the limiting approximation error into zero.'), ('Brouwer synthesis', 'What fundamentally distinguishes Brouwer from Banach?', 'Brouwer relies on topology of compact convex sets and gives existence; Banach relies on quantitative shrinking in complete metric spaces and gives uniqueness plus convergence.')], 'exercises': [('Does every continuous $[0,1]\\to[0,1]$ map have a fixed point?', 'Yes.', 'Yes.'), ('Can it have several?', 'Identity.', 'Yes.'), ('Does Brouwer guarantee uniqueness?', 'No.', 'No.'), ('Does compactness matter?', 'Open interval counterexample.', 'Yes.'), ('Does convexity appear in the standard theorem?', 'Yes.', 'Yes.'), ('Is a disk convex?', 'Straight segments stay inside.', 'Yes.'), ('Is a circle convex?', 'Chord leaves circle.', 'No.'), ('What one-dimensional theorem proves the interval case?', 'Intermediate value theorem.', 'IVT.')]}, 'II/18': {'intro': 'Integral equations encode unknown functions under an integral operator. Their analytic treatment combines norm estimates, compactness ideas, and fixed-point principles.', 'sections': [('Fredholm equations', 'The unknown appears under an integral over a fixed domain.'), ('Volterra equations', 'The upper limit depends on the evaluation point, producing a triangular time structure.'), ('Integral operators', 'Kernels define linear or nonlinear operators on function spaces.'), ('Sup-norm estimates', 'Kernel bounds convert integral operators into norm inequalities.'), ('Neumann series', 'Small operator norm permits inversion of $I-K$ by a geometric series.'), ('Contraction methods', "Nonlinear integral equations can be solved by Banach's theorem under Lipschitz conditions."), ('Iterated kernels', 'Repeated substitution creates iterated kernel integrals.'), ('Connection to ODEs', 'Initial-value ODEs are equivalent to Volterra integral equations.')], 'theorems': [('Neumann-series inversion', 'If a bounded linear operator $K$ satisfies $\\|K\\|<1$, then $I-K$ is invertible with $(I-K)^{-1}=\\sum_{n\\ge0}K^n$.', 'The operator series converges absolutely in norm, and finite geometric identities pass to the limit.'), ('Kernel sup bound', 'For $(Kf)(x)=\\int_a^b k(x,t)f(t)dt$, $\\|K\\|_\\infty\\le(b-a)\\|k\\|_\\infty$.', 'Take absolute values, bound both kernel and function by sup norms, and integrate interval length.'), ('Volterra contraction on short intervals', 'If $F(t,y)$ is Lipschitz in $y$ with constant $L$, the integral map $Ty=y_0+\\int_{t_0}^tF(s,y(s))ds$ is a contraction on an interval of length $h$ when $Lh<1$.', 'The output difference is at most $Lh$ times the input sup difference.')], 'dossiers': [('Constant kernel', 'Solve $f(x)=1+\\lambda\\int_0^1f(t)dt$.', 'Let $c=\\int_0^1f$. Then $f=1+\\lambda c$ is constant and $c=1+\\lambda c$, so for $\\lambda\\ne1$, $f=1/(1-\\lambda)$.'), ('Norm of a simple kernel operator', 'For $Kf(x)=\\int_0^1xtf(t)dt$, bound $\\|K\\|_\\infty$.', 'Since $|xt|\\le1$, the general bound gives $\\|K\\|\\le1$; the sharper bound is $1/2$ because $\\sup_x\\int_0^1xtdt=1/2$.'), ('Neumann approximation', 'If $\\|K\\|=q<1$, bound truncation after $N$ terms.', 'The inverse-series tail has norm at most $q^{N+1}/(1-q)$.'), ('Volterra uniqueness', 'Why are Volterra equations naturally compatible with iteration?', 'The value at time $t$ depends only on earlier times up to $t$, producing causal nested integrals and strong factorial-type bounds.'), ('ODE equivalence', "Convert $y'=f(t,y)$, $y(t_0)=y_0$ to an integral equation.", 'Integrate to obtain $y(t)=y_0+\\int_{t_0}^tf(s,y(s))ds$.'), ('Linear resolvent idea', 'What does $(I-\\lambda K)^{-1}$ represent?', 'It maps forcing terms to solutions of $f-\\lambda Kf=g$ when the inverse exists.'), ('Short-interval contraction', 'If Lipschitz constant is $L=3$, how small should interval length be for direct Banach contraction?', 'Choose $h<1/3$.'), ('Iterated operator estimate', 'If $\\|K\\|\\le q$, what is $\\|K^n\\|$?', 'At most $q^n$ by submultiplicativity.'), ('Kernel continuity', 'Why does a continuous kernel on a compact square define a bounded sup-norm operator?', 'The kernel is bounded by compactness, and the kernel sup bound applies.'), ('Nonlinear integral map', 'How does a Lipschitz nonlinearity enter the estimate?', 'Take the difference inside the integral and use the pointwise Lipschitz bound before integration.'), ('Fixed-point viewpoint', 'What equation is actually solved by Banach?', 'The integral equation is rewritten as $f=Tf$ and the solution is the unique fixed point of $T$.'), ('Integral-equation synthesis', 'Why are integral equations often easier than differential equations?', 'They encode initial conditions automatically and replace derivatives by averaging operators, which are better behaved in norm estimates.')], 'exercises': [('What operator solves $f=g+Kf$?', 'Rearrange.', '$(I-K)f=g$.'), ('When does Neumann series converge?', 'Operator norm below one.', 'If $\\|K\\|<1$.'), ('What norm is convenient on $C[a,b]$?', 'Sup norm.', '$\\|f\\|_\\infty$.'), ('What does a Volterra upper limit look like?', 'Variable upper endpoint.', '$\\int_a^x$.'), ('What does a Fredholm equation use?', 'Fixed interval.', '$\\int_a^b$.'), ('How do ODEs connect?', 'Integrate once.', 'They become Volterra equations.'), ('Why does short interval help?', 'Multiplies Lipschitz constant.', 'It makes $Lh<1$.'), ('Does $\\|K\\|<1$ imply uniqueness for $(I-K)f=g$?', 'Yes.', 'Yes, since $I-K$ is invertible.')]}, 'II/19': {'intro': 'Elementary ODE existence theory is most transparent when an initial-value problem is rewritten as an integral fixed-point equation. Continuity gives existence mechanisms; Lipschitz control supplies uniqueness.', 'sections': [('Initial-value problems', 'An ODE with initial data asks for a curve satisfying a differential rule and a point condition.'), ('Integral formulation', "Integrating converts $y'=f(t,y)$ into a Volterra equation."), ('Picard iteration', 'Successive substitution generates approximate solutions.'), ('Local existence', "Continuity and compactness can yield existence; Lipschitz hypotheses enable Banach's theorem."), ('Uniqueness', 'Lipschitz dependence on the state variable prevents branching solutions.'), ('Continuation', 'Solutions extend while they remain in regions where the hypotheses stay controlled.'), ('Continuous dependence', 'Small changes in initial data or vector field produce controlled changes in solutions.'), ('Autonomous systems', "Phase-space geometry reframes $y'=F(y)$ as a flow problem.")], 'theorems': [('Picard--Lindelöf', "If $f$ is continuous and locally Lipschitz in $y$ near $(t_0,y_0)$, then the IVP $y'=f(t,y)$, $y(t_0)=y_0$ has a unique local solution.", 'On a sufficiently small rectangle, the integral operator maps a closed sup-norm ball into itself and is a contraction; Banach gives a unique fixed point.'), ('Gronwall inequality', 'If $u(t)\\le A+B\\int_0^tu(s)ds$ with $u\\ge0$, then $u(t)\\le Ae^{Bt}$.', 'Define the right-hand side majorant and differentiate it; multiplying by $e^{-Bt}$ yields a monotone quantity that bounds $u$.'), ('Continuous dependence', 'Under a Lipschitz bound $L$, two solutions satisfy an exponential stability estimate controlled by initial separation.', 'Subtract the integral equations, estimate by the initial difference plus $L$ times the integral of the difference, then apply Gronwall.')], 'dossiers': [('Linear scalar IVP', "Solve $y'=ay$, $y(0)=y_0$.", 'The solution is $y(t)=y_0e^{at}$.'), ('Integral reformulation', "Rewrite $y'=t+y$, $y(0)=1$.", '$y(t)=1+\\int_0^t(s+y(s))ds$.'), ('Picard first iterate', 'Starting from $y_0(t)=1$, compute one Picard iterate for the previous equation.', '$y_1(t)=1+\\int_0^t(s+1)ds=1+t+t^2/2$.'), ('Uniqueness failure without Lipschitz', "Why can $y'=\\sqrt{|y|}$, $y(0)=0$ have nonunique solutions?", 'The square-root field is not Lipschitz at zero; solutions may remain zero for a while and then depart along a translated quadratic branch.'), ('Local contraction scale', 'If $|f(t,y)-f(t,z)|\\le L|y-z|$, what interval condition gives direct contraction?', 'Choose interval half-width or length $h$ with $Lh<1$.'), ('Gronwall stability', 'If two solutions have initial gap $\\delta$, bound their later gap.', 'Under Lipschitz constant $L$, the gap is at most $\\delta e^{L|t-t_0|}$.'), ('Blow-up and continuation', "Why does $y'=y^2$, $y(0)=1$ not extend for all positive time?", 'The solution $y=1/(1-t)$ blows up at $t=1$, leaving every bounded region where local continuation could proceed.'), ('Autonomous equilibrium', "What is an equilibrium of $y'=F(y)$?", 'A point $y_*$ with $F(y_*)=0$, giving the constant solution $y(t)=y_*$.'), ('Separable example', "Solve $y'=-2y$, $y(0)=3$.", '$y(t)=3e^{-2t}$.'), ('Parameter dependence', 'Why does a Lipschitz theorem imply robustness?', 'The same Gronwall estimate controlling uniqueness also bounds changes caused by perturbed initial data or forcing.'), ('Picard convergence', 'What makes successive approximations converge?', 'The integral operator is a contraction on a sufficiently small complete function-space ball.'), ('ODE synthesis', 'Why is integration the natural foundation for existence theory?', 'Differential equations ask for unknown derivatives, whereas the integral equation defines a self-map on a space of continuous functions where completeness and norm estimates can be applied.')], 'exercises': [("Solve $y'=y$, $y(0)=2$.", 'Exponential.', '$2e^t$.'), ('What theorem gives local uniqueness?', 'Picard--Lindelöf.', 'Picard--Lindelöf.'), ('What hypothesis controls uniqueness?', 'Lipschitz in state.', 'Local Lipschitz continuity in $y$.'), ('What does Gronwall control?', 'Growth of differences.', 'Exponential stability bounds.'), ('Can solutions blow up in finite time?', 'Yes.', "Yes, e.g. $y'=y^2$."), ('What is Picard iteration applied to?', 'Integral map.', 'The Volterra integral formulation.'), ('What is an equilibrium?', 'Zero of vector field.', 'A point $F(y_*)=0$.'), ('Does continuity alone always imply uniqueness?', 'No.', 'No.')]}, 'II/20': {'intro': 'Polynomial interpolation reconstructs a polynomial from finite data. Lagrange and Newton forms expose uniqueness, computation, divided differences, and the remainder term.', 'sections': [('Interpolation problem', 'Given distinct nodes and values, seek a polynomial matching all data.'), ('Lagrange basis', 'Cardinal polynomials isolate one node at a time.'), ('Uniqueness', 'A polynomial of degree at most $n$ matching $n+1$ distinct data points is unique.'), ('Newton form', 'Divided differences produce a nested incremental representation.'), ('Divided differences', 'Recursive coefficients encode discrete derivatives.'), ('Error formula', 'The interpolation remainder involves the next derivative and the node polynomial.'), ('Node choice', 'Equally spaced nodes can be unstable at high degree; special nodes reduce worst-case error.'), ('Hermite preview', 'Derivative data can be incorporated by repeated-node ideas.')], 'theorems': [('Interpolation existence and uniqueness', 'For $n+1$ distinct nodes, there is a unique polynomial of degree at most $n$ taking prescribed values.', 'Lagrange basis polynomials give existence. The difference of two interpolants has $n+1$ roots but degree at most $n$, so it is zero.'), ('Lagrange formula', 'The interpolant is $p(x)=\\sum_{j=0}^ny_jL_j(x)$ with $L_j(x_i)=\\delta_{ij}$.', 'By construction each basis polynomial is one at its own node and zero at the others, so the sum matches all data.'), ('Interpolation remainder', 'If $f\\in C^{n+1}$, then $f(x)-p_n(x)=f^{(n+1)}(\\xi)(\\prod_{j=0}^n(x-x_j))/(n+1)!$ for a suitable $\\xi$.', "Subtract a multiple of the node polynomial chosen to vanish also at $x$, then apply Rolle's theorem repeatedly to the resulting function.")], 'dossiers': [('Two-point interpolation', 'Interpolate $(0,1)$ and $(1,3)$.', 'The unique linear interpolant is $p(x)=1+2x$.'), ('Three-point Lagrange', 'Interpolate $f(0)=0,f(1)=1,f(2)=4$.', 'The data lie on $x^2$, so uniqueness gives $p(x)=x^2$.'), ('Uniqueness by roots', 'Why cannot two degree-$n$ interpolants agree at $n+1$ distinct nodes and differ elsewhere?', 'Their difference would be a nonzero degree-at-most-$n$ polynomial with too many roots.'), ('Lagrange basis property', 'Verify $L_j(x_i)=\\delta_{ij}$.', 'At $i=j$ all factors equal one; for $i\\ne j$ one numerator factor vanishes.'), ('Newton divided difference', 'Compute the first divided difference for data $(x_0,y_0),(x_1,y_1)$.', 'It is $(y_1-y_0)/(x_1-x_0)$.'), ('Incremental interpolation', 'Why is Newton form convenient when adding one new node?', 'The previous polynomial remains intact and one new product term is appended.'), ('Error node product', 'Why do roots of the interpolation error include all nodes?', 'The interpolant matches the function exactly at every node.'), ('Linear interpolation error', 'State the error form for two nodes.', "$f(x)-p_1(x)=f''(\\xi)(x-x_0)(x-x_1)/2$."), ('Runge warning', 'What can go wrong with high-degree equally spaced interpolation?', 'Endpoint oscillations can grow despite exact matching at nodes.'), ('Chebyshev motivation', 'Why choose nodes near Chebyshev points?', 'They reduce the maximum magnitude of the node polynomial and thereby control worst-case interpolation error.'), ('Vandermonde formulation', 'How can interpolation be written as a linear system?', 'Writing $p(x)=\\sum a_kx^k$ gives a Vandermonde matrix whose invertibility follows from distinct nodes.'), ('Interpolation synthesis', 'What is being approximated and what is exact?', 'The polynomial matches finitely many data exactly, while the remainder formula quantifies error between those nodes in terms of higher derivatives and node geometry.')], 'exercises': [('Interpolate two points $(0,0),(1,1)$.', 'Line through them.', '$p=x$.'), ('How many data points determine degree at most $n$?', 'Distinct nodes.', '$n+1$.'), ('Why distinct nodes?', 'Vandermonde determinant.', 'Otherwise uniqueness fails or data may conflict.'), ('What are Lagrange basis values at nodes?', 'Kronecker delta.', '$0$ or $1$.'), ('What degree is the node polynomial?', 'One factor per node.', '$n+1$.'), ('What theorem proves uniqueness?', 'Root count.', 'A nonzero degree-$n$ polynomial has at most $n$ roots.'), ('Does interpolation guarantee small error?', 'No.', 'Node placement and smoothness matter.'), ('What form supports incremental data?', 'Newton form.', 'Newton divided-difference form.')]}, 'II/21': {'intro': 'Polynomial approximation asks not for exact matching at finitely many points but for small error on an entire compact interval. The Weierstrass theorem says continuous functions admit arbitrarily accurate uniform polynomial approximations.', 'sections': [('Uniform approximation', 'Approximation quality is measured by the sup norm.'), ('Weierstrass theorem', 'Polynomials are dense in $C[a,b]$.'), ('Bernstein polynomials', 'On $[0,1]$, positive averaging polynomials give a constructive proof.'), ('Modulus of continuity', 'Uniform continuity controls approximation error.'), ('Shape preservation', 'Positive approximation operators can preserve positivity and convexity features.'), ('Density viewpoint', 'Approximation is a statement about closure of a subspace in a normed function space.'), ('Approximation rates', 'Extra smoothness improves quantitative convergence rates.'), ('Beyond polynomials', 'The same density philosophy leads to trigonometric and rational approximation.')], 'theorems': [('Weierstrass approximation theorem', 'Every continuous real function on $[a,b]$ can be uniformly approximated by polynomials.', 'After rescaling to $[0,1]$, Bernstein polynomials converge uniformly; uniform continuity controls nearby samples and binomial concentration controls distant samples.'), ('Bernstein reproduction', 'Bernstein operators reproduce constants and the identity function.', 'Binomial identities give $B_n1=1$ and $B_nx=x$.'), ('Density consequence', 'For every $f\\in C[a,b]$ and $\\varepsilon>0$, some polynomial $p$ satisfies $\\|f-p\\|_\\infty<\\varepsilon$.', 'This is exactly the statement that the polynomial subspace is dense in the sup-norm space.')], 'dossiers': [('Approximate absolute value', 'Why can $|x|$ on $[-1,1]$ be uniformly approximated by polynomials despite not being differentiable at zero?', 'Weierstrass requires continuity only, not differentiability.'), ('Bernstein constant', 'Show $B_n1=1$.', 'The Bernstein basis sums to $(x+(1-x))^n=1$.'), ('Bernstein identity', 'Show $B_nx=x$.', 'The weighted sum of $k/n$ against binomial probabilities equals the mean of a Binomial$(n,x)$ variable divided by $n$, namely $x$.'), ('Uniform versus pointwise approximation', 'Why is sup norm stronger?', 'It bounds the worst error at every point simultaneously rather than allowing the bad point to vary with the approximant.'), ('Density interpretation', 'What does polynomial density mean geometrically?', 'Every open sup-norm ball around every continuous function contains a polynomial.'), ('No exact representation required', 'Does Weierstrass say every continuous function is a polynomial?', 'No; it says polynomials can approach arbitrarily closely in sup norm.'), ('Approximation of $e^x$', 'Give one natural polynomial approximant.', 'Taylor polynomials provide explicit approximants; on a compact interval their remainders can be bounded uniformly.'), ('Approximation and integration', 'If $p_n\\to f$ uniformly, what happens to integrals?', 'The integrals converge because integration is continuous in the sup norm.'), ('Approximation and roots', 'Does a uniformly close polynomial necessarily preserve every zero?', 'No; zeros can move or disappear unless extra sign or transversality information is available.'), ('Smoothness and rate', 'Why should smoother functions be easier to approximate rapidly?', 'Higher regularity controls oscillation and derivative growth, enabling sharper remainder and constructive approximation estimates.'), ('Positive operators', 'Why are Bernstein polynomials stable?', 'They are convex combinations of sampled values, so they do not amplify the sup norm and preserve positivity.'), ('Approximation synthesis', 'How does this differ from interpolation?', 'Interpolation enforces exact agreement at selected points; approximation minimizes or controls global error across the whole interval.')], 'exercises': [('What norm does Weierstrass use?', 'Sup norm.', 'Uniform norm.'), ('Must $f$ be differentiable?', 'No.', 'Continuity suffices.'), ('What interval is standard for Bernstein polynomials?', '$[0,1]$.', '$[0,1]$.'), ('Do Bernstein polynomials reproduce constants?', 'Yes.', 'Yes.'), ('Do they reproduce $x$?', 'Yes.', 'Yes.'), ('Does density mean equality?', 'No.', 'Arbitrarily close approximation.'), ('Does uniform approximation imply integral approximation?', 'Yes.', 'Yes on compact intervals.'), ('Can $|x|$ be polynomially approximated uniformly?', 'Yes.', 'Yes.')]}, 'II/22': {'intro': 'Chebyshev and minimax approximation focus on worst-case uniform error. Equioscillation and Chebyshev polynomials reveal why optimal approximants spread their error rather than concentrating it.', 'sections': [('Minimax problem', 'Choose an approximant minimizing the maximum absolute error.'), ('Chebyshev polynomials', '$T_n(\\cos\\theta)=\\cos(n\\theta)$ oscillates between $\\pm1$ with controlled leading coefficient.'), ('Extremal property', 'Among monic degree-$n$ polynomials, a scaled Chebyshev polynomial minimizes sup norm on $[-1,1]$.'), ('Equioscillation', 'Optimal errors alternate in sign at enough extremal points.'), ('Uniqueness', 'Alternation forces uniqueness of the best approximant in classical polynomial spaces.'), ('Node placement', 'Chebyshev extrema and zeros guide stable interpolation and quadrature.'), ('Error scaling', 'Affine changes transfer results from $[-1,1]$ to any compact interval.'), ('Numerical viewpoint', 'Minimax approximation optimizes worst-case performance rather than average error.')], 'theorems': [('Chebyshev extremal property', 'The monic polynomial $2^{1-n}T_n$ has minimal sup norm among all monic degree-$n$ polynomials on $[-1,1]$.', 'If another monic polynomial had smaller norm, their difference would have degree at most $n-1$ yet would change sign between the $n+1$ alternating extrema of the Chebyshev polynomial, forcing at least $n$ roots, contradiction.'), ('Alternation criterion', 'A best degree-at-most-$n$ uniform approximant to a continuous function is characterized by at least $n+2$ alternating extremal error points.', 'If alternation fails, one can perturb within the approximation space to reduce the maximum error; if alternation holds, any competitor difference has too many sign changes for its degree.'), ('Uniqueness of minimax polynomial', 'The best uniform polynomial approximant of prescribed degree is unique.', 'Two distinct best approximants averaged together would force a smaller maximum error unless their error extrema align; alternation then forces their difference to have too many zeros.')], 'dossiers': [('Compute low Chebyshev polynomials', 'Find $T_0,T_1,T_2,T_3$.', 'From $T_n(\\cos\\theta)=\\cos n\\theta$: $1,x,2x^2-1,4x^3-3x$.'), ('Recurrence', 'Derive $T_{n+1}=2xT_n-T_{n-1}$.', 'Use $\\cos((n+1)\\theta)=2\\cos\\theta\\cos n\\theta-\\cos((n-1)\\theta)$.'), ('Extrema', 'Where does $T_n$ attain $\\pm1$?', 'At $x_k=\\cos(k\\pi/n)$, $k=0,\\dots,n$.'), ('Zeros', 'Where are the zeros of $T_n$?', 'At $\\cos((2k-1)\\pi/(2n))$, $k=1,\\dots,n$.'), ('Monic scaling', 'Why multiply by $2^{1-n}$?', 'For $n\\ge1$, the leading coefficient of $T_n$ is $2^{n-1}$, so scaling makes it monic.'), ('Worst-case interpretation', 'What does minimax optimize?', 'The largest absolute error over the entire interval.'), ('Alternating errors', 'Why should an optimum touch both positive and negative error extremes?', 'If all extreme errors had the same sign, a small vertical shift would reduce the maximum magnitude.'), ('Linear approximation intuition', 'For degree one, how many alternating extremal points characterize the minimax fit?', 'At least three.'), ('Affine rescaling', 'How do Chebyshev points transfer to $[a,b]$?', 'Map $x\\in[-1,1]$ by $(a+b)/2+(b-a)x/2$.'), ('Interpolation connection', 'Why do Chebyshev nodes reduce endpoint problems?', 'They cluster near endpoints, reducing the maximum node-polynomial magnitude.'), ('Uniqueness mechanism', 'How does root counting enter minimax uniqueness?', 'Alternating error inequalities force the difference of two candidates to change sign too many times for its degree.'), ('Minimax synthesis', 'How is minimax different from least squares?', 'Minimax controls the maximum error; least squares minimizes an integrated squared error and may tolerate larger localized peaks.')], 'exercises': [('What is $T_2$?', 'Use recurrence.', '$2x^2-1$.'), ('What is $T_3$?', 'Use recurrence.', '$4x^3-3x$.'), ('What is $\\|T_n\\|_\\infty$ on $[-1,1]$?', 'Cosine definition.', '$1$.'), ('How many extrema are used in alternation for degree $n$?', 'One more than dimension.', 'At least $n+2$.'), ('Are Chebyshev zeros equally spaced in $x$?', 'They are equally spaced in angle.', 'No.'), ('Why scale $T_n$ to monic?', 'Compare monic polynomials.', 'To formulate the extremal property.'), ('What norm is minimized?', 'Sup norm.', 'Uniform norm.'), ('Does minimax equal least squares?', 'Generally no.', 'No.')]}, 'II/23': {'intro': 'The alternation principle is the structural certificate for best uniform approximation. It converts an optimization problem into a finite pattern of equal-magnitude alternating errors.', 'sections': [('Error function', 'For approximant $p$, study $e=f-p$.'), ('Extreme points', 'Minimax optimality is witnessed where $|e|$ reaches its sup norm.'), ('Alternation pattern', 'Signs alternate at successive extremal points.'), ('Necessity', 'Without enough alternation one can construct a perturbation reducing the maximum error.'), ('Sufficiency', 'Enough alternating extrema block every lower-degree perturbation by root counting.'), ('Uniqueness', 'Two best approximants would force their difference to have too many zeros.'), ('Remez idea', 'Algorithms update candidate alternation points until equal error levels stabilize.'), ('Approximation certificates', 'Alternation gives a verifiable finite certificate of global optimality.')], 'theorems': [('Chebyshev alternation theorem', 'A polynomial $p$ of degree at most $n$ is best uniform approximation to continuous $f$ on $[a,b]$ iff the error attains its maximum magnitude at at least $n+2$ ordered points with alternating signs.', 'Sufficiency follows because any better competitor would force the difference polynomial to change sign between each adjacent pair, producing more roots than its degree. Necessity follows from a separation/perturbation argument when no such alternating set exists.'), ('Uniqueness', 'The best degree-$n$ uniform polynomial approximant is unique.', 'If two best approximants existed, alternation for one and the competitor inequalities would force their difference to have at least $n+1$ zeros despite degree at most $n$.'), ('Finite certificate', 'Once $n+2$ alternating equal-magnitude error points are verified, global minimax optimality follows.', 'This is the sufficiency direction of the alternation theorem.')], 'dossiers': [('Constant approximation', 'How many alternating points certify a best constant approximant?', 'Two points with errors $+E$ and $-E$; the best constant centers the range between maximum and minimum values.'), ('Best constant formula', 'For continuous $f$, find the best constant in sup norm.', 'It is $(M+m)/2$, where $M=\\max f$ and $m=\\min f$, with error $(M-m)/2$.'), ('Degree-one certificate', 'How many alternating extrema certify a best line?', 'Three.'), ('Why equal magnitude?', 'Why must active extrema in the alternation pattern have the same magnitude?', 'If one were strictly smaller, the true sup norm would be determined elsewhere and the finite optimality certificate would not be balanced.'), ('Root-count sufficiency', 'Explain the sign-change argument.', 'A uniformly better competitor must lie closer to $f$ at each alternating extremum, forcing the difference of the two approximants to alternate sign between consecutive extremal points and thus have too many roots.'), ('Uniqueness', 'Why can two different minimax polynomials not share the same alternation certificate?', 'Their difference would need to vanish or change sign in too many intervals for its degree.'), ('Remez iteration', 'What does a Remez step update?', 'It solves for an approximant and common error level on a chosen alternating set, then replaces points using extrema of the new error.'), ('Error centering', 'For constant approximation, why center the maximum and minimum?', 'Any shift away from the midpoint increases the larger of the two endpoint range deviations.'), ('Monotone target', 'If $f$ is monotone, where are extreme errors for the best constant?', 'At points attaining the minimum and maximum of $f$.'), ('Certificate versus search', 'Why is alternation valuable computationally?', 'Searching for the optimum is global, but once a candidate displays the required alternation, optimality can be certified finitely.'), ('Generalized spaces', 'What property of polynomials enables alternation arguments?', 'A nonzero degree-$n$ polynomial cannot have more than $n$ roots; more generally Chebyshev systems have controlled zero counts.'), ('Alternation synthesis', 'What does the theorem reveal conceptually?', 'Best worst-case approximations distribute their unavoidable error evenly with alternating sign rather than allowing one-sided or localized excess.')], 'exercises': [('Best constant to $f$ uses which values?', 'Maximum and minimum.', 'Their midpoint.'), ('How many points for degree $n$?', '$n+2$.', 'At least $n+2$.'), ('What alternates?', 'Error sign.', 'Signs of extremal error.'), ('What is equal?', 'Error magnitude.', 'The sup error magnitude.'), ('What proves sufficiency?', 'Root count.', 'Sign changes and root counting.'), ('What algorithm uses alternation?', 'Remez.', 'Remez algorithm.'), ('Is minimax best approximant unique?', 'For polynomials, yes.', 'Yes.'), ('What norm is involved?', 'Sup norm.', 'Uniform norm.')]}, 'II/24': {'intro': 'Numerical quadrature replaces an integral by a weighted finite sum of function values. Interpolation gives a systematic derivation, while error formulas explain exactness and the role of node placement.', 'sections': [('Quadrature rules', 'Approximate $\\int_a^bf$ by $\\sum w_if(x_i)$.'), ('Interpolatory quadrature', 'Integrate an interpolation polynomial exactly to obtain weights.'), ('Newton--Cotes rules', 'Equally spaced nodes yield midpoint, trapezoidal, Simpson, and higher rules.'), ('Degree of exactness', 'A rule has degree $m$ if it integrates all polynomials through degree $m$ exactly.'), ('Error formulas', 'Remainders depend on higher derivatives and powers of step size.'), ('Composite rules', 'Apply a low-order rule repeatedly on a fine partition.'), ('Gaussian quadrature', 'Optimally chosen nodes increase polynomial exactness for a fixed number of samples.'), ('Stability and adaptivity', 'Practical quadrature balances truncation error, smoothness, and sampling cost.')], 'theorems': [('Trapezoidal error', "For $f\\in C^2[a,b]$, the one-panel trapezoidal error equals $-(b-a)^3f''(\\xi)/12$ for some $\\xi$.", 'Integrate the linear interpolation remainder or use a Peano-kernel argument.'), ('Simpson exactness', "Simpson's rule is exact for polynomials of degree at most three.", 'Check the rule on the basis $1,x,x^2,x^3$ after affine reduction to a symmetric interval.'), ('Gaussian exactness', 'An $n$-node Gaussian rule for a positive weight is exact for polynomials through degree $2n-1$.', 'Orthogonal-polynomial nodes make the error polynomial divisible by the degree-$n$ orthogonal polynomial; division separates any degree-$2n-1$ polynomial into a vanishing part plus a lower-degree remainder integrated exactly by the weights.')], 'dossiers': [('Midpoint rule', 'Approximate $\\int_0^1x^2dx$ by one midpoint sample.', 'The midpoint value is $1/4$, so the one-panel approximation is $1/4$ versus exact $1/3$.'), ('Trapezoidal rule', 'Approximate the same integral.', '$(f(0)+f(1))/2=1/2$.'), ('Simpson rule', 'Apply Simpson to $x^2$ on $[0,1]$.', '$(1/6)(f(0)+4f(1/2)+f(1))=(1/6)(0+1+1)=1/3$, exact.'), ('Degree of exactness', 'Why is trapezoidal exact for linear functions?', 'It integrates the linear interpolant, which equals the function itself for degree at most one.'), ('Composite trapezoid', 'What changes when the interval is subdivided?', 'Apply trapezoidal rule on each subinterval and sum; the global error decreases like $h^2$ under smoothness.'), ('Composite Simpson', 'What order is expected?', 'For sufficiently smooth functions the global error behaves like $h^4$.'), ('Interpolatory weights', 'How are weights obtained?', 'Integrate each Lagrange cardinal polynomial over the interval.'), ('Positive weights', 'Why are positive quadrature weights desirable?', 'They improve stability and preserve positivity for nonnegative sampled data.'), ('Gaussian advantage', 'Why can $n$ Gaussian nodes beat $n$ equally spaced interpolatory nodes?', 'The nodes are optimized jointly with weights, yielding degree of exactness $2n-1$.'), ('Error and smoothness', 'Why do high-order rules need higher derivatives?', 'Their error formulas involve higher derivatives; without regularity, formal high order may not translate into actual accuracy.'), ('Adaptive idea', 'How does adaptive quadrature choose where to sample more?', 'Estimate local error on subintervals and refine where the estimate is largest.'), ('Quadrature synthesis', 'How is quadrature connected to interpolation?', 'Interpolatory quadrature integrates a polynomial surrogate exactly; the quadrature error is therefore the integral of the interpolation error.')], 'exercises': [('Degree of trapezoidal exactness?', 'Linear.', '$1$.'), ('Degree of Simpson exactness?', 'Cubic.', '$3$.'), ('What does Gaussian $n$-point exactness reach?', '$2n-1$.', 'Degree $2n-1$.'), ('Why composite rules?', 'Reduce step size.', 'To lower error on long intervals.'), ('What are quadrature weights?', 'Integrated basis functions.', 'Coefficients multiplying samples.'), ('Is Simpson exact for $x^4$?', 'No.', 'Not generally.'), ('What smoothness controls trapezoidal error?', 'Second derivative.', "A bound on $f''$."), ('What is adaptive refinement based on?', 'Local error estimates.', 'Estimated local error.')]}, 'II/25': {'intro': 'Continued fractions provide a discrete approximation theory for real numbers. Their convergents are exceptionally good rational approximants and connect Euclidean algorithms, Diophantine approximation, and recursive computation.', 'sections': [('Simple continued fractions', 'Write a real number as $[a_0;a_1,a_2,\\ldots]$ with positive integer partial quotients after the first.'), ('Euclidean algorithm', 'Rational continued fractions terminate and encode the Euclidean algorithm.'), ('Convergents', 'Truncating the expansion gives rational approximants $p_n/q_n$.'), ('Recurrences', 'Numerators and denominators satisfy second-order recurrences.'), ('Determinant identity', 'Adjacent convergents satisfy $p_nq_{n-1}-p_{n-1}q_n=(-1)^{n-1}$.'), ('Approximation quality', 'Convergents approximate unusually well relative to their denominators.'), ('Quadratic irrationals', 'Eventually periodic continued fractions characterize quadratic irrationals.'), ('Approximation perspective', 'Continued fractions complement polynomial approximation by optimizing arithmetic rather than functional error.')], 'theorems': [('Convergent recurrences', 'With standard initial data, $p_n=a_np_{n-1}+p_{n-2}$ and $q_n=a_nq_{n-1}+q_{n-2}$.', 'Induct by rewriting the finite continued fraction after adjoining its last partial quotient.'), ('Adjacent determinant identity', '$p_nq_{n-1}-p_{n-1}q_n=(-1)^{n-1}$.', 'Insert the recurrences and observe the determinant changes sign at each step.'), ('Basic approximation bound', 'For an irrational simple continued fraction, $|x-p_n/q_n|<1/q_n^2$ for infinitely many convergents, and standard sharper neighboring-denominator bounds hold for every convergent.', 'Express $x$ using the complete quotient after stage $n$ and combine with the determinant identity; the denominator in the exact error formula exceeds $q_n^2$ at the appropriate stages.')], 'dossiers': [('Rational expansion', 'Find a continued fraction for $17/7$.', 'Euclidean algorithm: $17=2\\cdot7+3$, $7=2\\cdot3+1$, $3=3\\cdot1$, so $17/7=[2;2,3]$.'), ('Convergents of $[1;1,1,\\dots]$', 'Identify the convergents.', 'They are ratios of consecutive Fibonacci numbers.'), ('Golden ratio', 'Show $\\varphi=[1;1,1,1,\\dots]$.', 'The tail equals the whole number, so $x=1+1/x$, giving $x^2-x-1=0$ and the positive root $\\varphi$.'), ('Recurrence computation', 'Given partial quotients $a_0,a_1,a_2$, compute $p_2,q_2$ recursively.', 'Use $p_{-2}=0,p_{-1}=1$, $q_{-2}=1,q_{-1}=0$, then apply the stated recurrences.'), ('Neighbor difference', 'Use the determinant identity to compute $|p_n/q_n-p_{n-1}/q_{n-1}|$.', 'It equals $1/(q_nq_{n-1})$.'), ('Why denominators grow', 'Show $q_n>q_{n-1}$ for simple continued fractions beyond the first stage.', 'Since $a_n\\ge1$ and $q_{n-2}\\ge0$, $q_n=a_nq_{n-1}+q_{n-2}\\ge q_{n-1}$, with strict growth once positive preceding terms occur.'), ('Best-approximation intuition', 'Why are convergents hard to beat?', 'The determinant identity forces nearby rational competitors with small denominators to remain separated, while the continued-fraction error is already on the order of inverse denominator squared.'), ('Finite expansion ambiguity', 'Why can a rational have two finite simple continued fraction expansions?', 'A final partial quotient $a_n>1$ can be replaced by $a_n-1,1$, producing the same value.'), ('Square root periodicity', 'What is special about continued fractions of quadratic irrationals?', 'Their partial quotients are eventually periodic, and conversely eventual periodicity characterizes quadratic irrationals.'), ('Euclidean algorithm link', 'Why do rationals terminate?', 'Repeated reciprocal-and-floor steps reproduce Euclidean remainders, which eventually reach zero.'), ('Approximation scale', 'What does an error of order $1/q^2$ mean?', 'Doubling denominator can reduce error quadratically in the ideal scale, much better than a generic grid spacing of order $1/q$.'), ('Continued-fraction synthesis', 'How does this chapter fit the approximation part of the volume?', 'Earlier chapters approximate functions globally; continued fractions approximate numbers arithmetically, using recursive discrete structure to obtain near-optimal rational approximants.')], 'exercises': [('Find CF of $3/2$.', 'Euclidean algorithm.', '$[1;2]$.'), ('What are convergents?', 'Finite truncations.', 'Rational truncations of the continued fraction.'), ('What algorithm computes rational CFs?', 'Euclidean algorithm.', 'Euclidean algorithm.'), ('What famous CF has all ones?', 'Golden ratio.', '$\\varphi$.'), ('How do $q_n$ behave?', 'They grow.', 'They increase after the initial stages.'), ('What identity relates adjacent convergents?', 'Determinant identity.', '$p_nq_{n-1}-p_{n-1}q_n=\\pm1$.'), ('What numbers have eventually periodic CFs?', 'Quadratic irrationals.', 'Exactly quadratic irrationals.'), ('What error scale do convergents achieve?', 'About inverse-square denominator.', 'Order $1/q_n^2$.')]}}
